  card.dataset.sym=sym.toUpperCase();card.dataset.name=nm;card.dataset.us=us?"1":"0";
  var d=get(sym,[sym]),key=sym+"|"+(d?d.at||"x":"wait");if(key===OK){if(OCH){var el0=document.getElementById("owMap");if(el0&&el0.clientWidth&&el0.clientWidth!==OW){OW=el0.clientWidth;OCH.resize()}}return}
