  var cur=CS(d.cur),mj=d.major||{},nt=d.net||{},HO=(d.inst||[]).concat((d.funds||[]).map(function(x){return Object.assign({fund:1},x)}));
  var tx=(d.insTx||[]).map(function(t){return Object.assign({k:txKind(t.txt)},t)}),open=tx.filter(function(t){return t.k[0]==="매수"||t.k[0]==="매도"});
  var d90=Date.now()-90*864e5,o90=open.filter(function(t){return Date.parse(t.d)>=d90}),bv=0,sv=0,bn={},sn={};o90.forEach(function(t){if(t.k[0]==="매수"){bv+=t.val||0;bn[t.who]=1}else{sv+=t.val||0;sn[t.who]=1}});
  var nb=Object.keys(bn).length,ns=Object.keys(sn).length,sig=nb>ns&&bv>sv?["매수 우위","up"]:ns>nb&&sv>bv?["매도 우위","dn"]:["중립",""];
  var H='<h2>보유 · 내부자 거래 <span class="st-hint">'+E(d.symbol)+" · "+E(nm)+" · 기관 13F · 내부자 Form 4 · "+E(d.src)+"</span></h2>";
  H+='<div class="ow-kpi"><div><span>기관 보유</span><b>'+(mj.inst!=null?(mj.inst*100).toFixed(1)+"%":"-")+"</b><small>"+(mj.count?num2(mj.count)+"곳":"")+'</small></div><div><span>내부자 보유</span><b>'+(mj.insiders!=null?(mj.insiders*100).toFixed(2)+"%":"-")+'</b><small>임원 · 대주주</small></div><div><span>내부자 신호 (90일)</span><b class="'+sig[1]+'">'+sig[0]+"</b><small>매수 "+nb+"명 · 매도 "+ns+'명</small></div><div><span>공개시장 매수 (90일)</span><b class="up">'+big(bv,cur)+"</b><small>"+o90.filter(function(t){return t.k[0]==="매수"}).length+'건</small></div><div><span>공개시장 매도 (90일)</span><b class="dn">'+big(sv,cur)+"</b><small>"+o90.filter(function(t){return t.k[0]==="매도"}).length+'건</small></div><div><span>6개월 순매수 (보상 포함)</span><b class="'+cls(nt.netSh)+'">'+big(nt.netSh)+"주</b><small>매수 "+(nt.buyN||0)+"건 · 매도 "+(nt.sellN||0)+"건</small></div></div>";
  H+='<div class="ow-grid"><div><h3>내부자 거래 내역 <small>공개시장 매수 · 매도 먼저 · 사전 계획 매도 (10b5-1) 여부는 이 자료에 없음</small></h3><div class="ow-scroll ow-h"><table class="ow-t"><thead><tr><th>날짜</th><th class="l">이름</th><th class="l">직책</th><th>구분</th><th>주식 수</th><th>금액</th></tr></thead><tbody>'+(tx.length?open.concat(tx.filter(function(t){return open.indexOf(t)<0})).slice(0,40).map(function(t){return'<tr><td class="nm">'+E(t.d||"-")+'</td><td class="l">'+E(t.who||"")+'</td><td class="l">'+E(t.role||"")+'</td><td class="'+t.k[1]+'">'+t.k[0]+"</td><td>"+big(t.sh)+"</td><td>"+(t.val?big(t.val,cur):"-")+"</td></tr>"}).join(""):'<tr><td colspan="6" class="st-hint">최근 내부자 거래 신고가 없습니다 (미국 상장 종목만 제공)</td></tr>')+"</tbody></table></div></div>";
